# Anti-pattern: uniform TTL in midnight batch warmer
for product in top_120k_products:
    redis.set(f"prod:{product.id}", serialize(product), ex=3600)  # All expire at 01:00:00Z!

// Java Caffeine L1 fallback with async refreshAfterWrite
LoadingCache<String, Product> l1Cache = Caffeine.newBuilder()
    .maximumSize(10_000)
    .refreshAfterWrite(Duration.ofSeconds(30))
    .expireAfterWrite(Duration.ofSeconds(120))
    .build(key -> redisOrDbFetch(key));

db_sem = asyncio.Semaphore(10)

async def protected_db_fetch(db, l1_cache, key):
    if db_sem.locked() and key in l1_cache:
        return l1_cache[key]  # Shed load to L1 stale
    async with db_sem:
        return await asyncio.wait_for(db.fetch_product(key), timeout=0.5)
